for n,x,y,k,e,unit in [(32,20/math.sqrt(2)+8*math.sqrt(3),20/math.sqrt(2)-8,'양의x축에서45°의20lb 힘과 −30°의16lb 힘의 합력 크기·방향을 구하라.','Find the resultant magnitude and direction for20lb at45° and16lb at−30°.','lb'),(33,-200,100*math.sqrt(3),'왼쪽300N 힘과 양의x축에서60°인200N 힘의 합력 크기·방향을 구하라.','Find the resultant magnitude and direction for300N leftward plus200N at60°.','N')]:
 mag=math.hypot(x,y);ang=math.degrees(math.atan2(y,x));add(n,k,e,[m(fr'R=\langle{x:.6f},{y:.6f}\rangle'),m(r'|R|=\sqrt{R_x^2+R_y^2},\quad\theta=\operatorname{atan2}(R_y,R_x)')],[m(fr'R=\langle{x:.6f},{y:.6f}\rangle'),m(r'|R|=\sqrt{R_x^2+R_y^2},\quad\theta=\operatorname{atan2}(R_y,R_x)')],m(fr'|R|\approx{mag:.3f},\quad\theta\approx{ang:.3f}^\circ')+'; '+unit,ck='성분의 부호에 맞는 사분면을 선택했다.',ce='The quadrant agrees with the component signs.')
