east=-180/math.sqrt(2)+35/2;north=180/math.sqrt(2)-35*math.sqrt(3)/2;speed=math.hypot(east,north);angle=math.degrees(math.atan2(-east,north))
add(39,'비행기가 N45°W로 대기속력180mi/h로 가고 바람은 S30°E 방향35mi/h이다. 실제 진로와 지상속력을 구하라.','A plane heads N45°W at180mi/h; wind blows toward S30°E at35mi/h. Find its track and ground speed.',[m(r'v=\langle-180/\sqrt2+35/2,\ 180/\sqrt2-35\sqrt3/2\rangle')],[m(r'v=\langle-180/\sqrt2+35/2,\ 180/\sqrt2-35\sqrt3/2\rangle')],m(fr'\mathrm{{N}}{angle:.3f}^\circ\mathrm{{W}},\quad |v|\approx{speed:.3f}\ \mathrm{{mi/h}}'),ck='바람은 S30°E로 향하는 것으로 주어졌다. 출발 방향을 뜻하는 기상식표현과 구별한다.',ce='The wind is specified as blowing toward S30°E, not from that direction.')
add(40,'배는서쪽32km/h, 개는갑판 위에서북쪽4km/h로 달린다. 수면에 대한 개의 속력·방향을 구하라.','A ship moves west32km/h; a dog runs north4km/h on deck. Find the dog’s speed and direction relative to the water.',[m(r'v=\langle-32,4\rangle,\quad |v|=\sqrt{32^2+4^2}=4\sqrt{65}')],[m(r'v=\langle-32,4\rangle,\quad |v|=\sqrt{32^2+4^2}=4\sqrt{65}')],m(r'|v|=4\sqrt{65}\approx32.249\ \mathrm{km/h},\quad\mathrm{N}82.875^\circ\mathrm{W}'),ck='서쪽에서 북쪽으로7.125°와 같은 방향이다.',ce='Equivalently, the direction is7.125° north of west.')
add(41,m('y=x^2')+'의(2,4)에서 접선과 평행한 단위벡터들을 구하라.','Find unit vectors parallel to the tangent of '+m('y=x^2')+' at(2,4).',[m(r'y\prime(2)=4,\quad d=\langle1,4\rangle,\quad|d|=\sqrt{17}')],[m(r'y\prime(2)=4,\quad d=\langle1,4\rangle,\quad|d|=\sqrt{17}')],m(r'\pm\frac{1}{\sqrt{17}}\langle1,4\rangle'),ck='서로 반대인 두 방향 모두 접선과 평행하다.',ce='Both opposite directions are parallel to the tangent.')
add(42,m(r'y=2\sin x')+'의 '+m(r'(\pi/6,1)')+'에서(a)접선에 평행한 단위벡터들,(b)수직인 단위벡터들,(c)모두 그 점에서 시작하는 그림을 구하라.','At '+m(r'(\pi/6,1)')+' on '+m(r'y=2\sin x')+', find(a)parallel tangent unit vectors,(b)perpendicular unit vectors,(c)draw all starting at the point.',[m(r'y\prime(\pi/6)=2\cos(\pi/6)=\sqrt3'),m(r'd=\langle1,\sqrt3\rangle,\quad n=\langle-\sqrt3,1\rangle,\quad |d|=|n|=2')],[m(r'y\prime(\pi/6)=2\cos(\pi/6)=\sqrt3'),m(r'd=\langle1,\sqrt3\rangle,\quad n=\langle-\sqrt3,1\rangle,\quad |d|=|n|=2')],m(r'(a)\ \pm\langle1/2,\sqrt3/2\rangle,\quad(b)\ \pm\langle-\sqrt3/2,1/2\rangle'),parts=list('abc'),ck='두 대표 벡터의 내적은0이고 각 길이는1이다.',ce='The representative vectors have zero dot product and unit lengths.')
add(43,'삼각형ABC의 AB+BC+CA를 구하라(유향선분).','Find AB+BC+CA for triangle ABC using directed segments.',[m(r'(B-A)+(C-B)+(A-C)=0')],[m(r'(B-A)+(C-B)+(A-C)=0')],m(r'\overrightarrow{AB}+\overrightarrow{BC}+\overrightarrow{CA}=\mathbf0'),ck='출발점으로 돌아오는 전체 변위는0이다.',ce='A closed trip has zero displacement.')
add(44,'C는 선분AB 위에서 B까지 거리가 A까지 거리의2배인 점이다. 위치벡터a,b,c에 대해 c=(2a+b)/3임을 보여라.','C lies on segment AB with distance to B twice its distance to A. Prove the position-vector formula c=(2a+b)/3.',[m(r'AC:CB=1:2,\quad c=a+\frac13(b-a)')],[m(r'AC:CB=1:2,\quad c=a+\frac13(b-a)')],m(r'c=\frac23a+\frac13b'),ck='c−a=(b−a)/3, b−c=2(b−a)/3이다.',ce='c−a=(b−a)/3 and b−c=2(b−a)/3.')
add(45,m(r'a=\langle3,2\rangle,b=\langle2,-1\rangle,c=\langle7,1\rangle')+'를(a)그리고(b)c=sa+tb를 그림으로 설명하고(c)s,t를 추정한 뒤(d)정확히 구하라.','For '+m(r'a=\langle3,2\rangle,b=\langle2,-1\rangle,c=\langle7,1\rangle')+', (a)plot the vectors,(b)illustrate c=sa+tb,(c)estimate s,t,(d)find exact values.',[m(r'3s+2t=7,\quad2s-t=1'),m(r't=2s-1,\quad7s=9,\quad s=9/7,\ t=11/7')],[m(r'3s+2t=7,\quad2s-t=1'),m(r't=2s-1,\quad7s=9,\quad s=9/7,\ t=11/7')],m(r's=9/7\approx1.286,\quad t=11/7\approx1.571'),parts=list('abcd'),ck='선형결합의 성분은(27/7+22/7,18/7−11/7)=(7,1)이다.',ce='The combination is(27/7+22/7,18/7−11/7)=(7,1).')
add(46,'0이 아니고 평행하지 않은 a,b가 만드는 평면의 임의벡터c가 sa+tb로 표현됨을 기하·성분 두 방법으로 설명하라.','Give geometric and component arguments that nonparallel nonzero vectors a,b span every c in their plane.',['기하: c의 끝점을 지나 a,b에 각각 평행한 직선을 그리면 a,b방향의 두 변으로 된 평행사변형을 얻는다. 변들의 부호있는 배수를 s,t로 둔다.',m(r'\det\begin{pmatrix}a_1&b_1\\a_2&b_2\end{pmatrix}\ne0'),'성분: 평면 안에 직교좌표를 잡으면 위 행렬식이0이 아니므로 두 성분의 연립방정식은 유일한 해를 갖는다.'],['Geometrically, lines through the tip of c parallel to a and b complete a parallelogram with signed side multiples s,t.',m(r'\det\begin{pmatrix}a_1&b_1\\a_2&b_2\end{pmatrix}\ne0'),'In orthonormal coordinates within the plane, the nonzero determinant gives a unique solution for the two components.'],m(r'c=sa+tb'),ck='비평행 조건이 행렬식이0이 아니라는 조건과 동치이다.',ce='Nonparallelism is equivalent to the nonzero determinant.')
add(47,m(r'r=\langle x,y,z\rangle,r_0=\langle x_0,y_0,z_0\rangle,\quad|r-r_0|=1')+'의 자취를 설명하라.','Describe the locus '+m(r'r=\langle x,y,z\rangle,r_0=\langle x_0,y_0,z_0\rangle,\quad|r-r_0|=1')+'.',[m(r'(x-x_0)^2+(y-y_0)^2+(z-z_0)^2=1')],[m(r'(x-x_0)^2+(y-y_0)^2+(z-z_0)^2=1')],'중심(x₀,y₀,z₀), 반지름1인 구면.','The sphere centered at(x₀,y₀,z₀) with radius1.',ck='고정점까지의 거리를1로 고정한 자취이다.',ce='Distance to the fixed center is exactly1.')
add(48,m(r'r=\langle x,y\rangle,\quad |r-r_1|+|r-r_2|=k>|r_1-r_2|')+'의 자취를 설명하라.','Describe '+m(r'r=\langle x,y\rangle,\quad |r-r_1|+|r-r_2|=k>|r_1-r_2|')+'.',[r'두 고정점까지 거리의 합이 일정하므로 타원이다. 장반경은k/2이다.',m(r'a=k/2,\quad c=|r_1-r_2|/2,\quad b=\tfrac12\sqrt{k^2-|r_1-r_2|^2}')],[r'A constant sum of distances to two fixed foci defines an ellipse with semimajor axis k/2.',m(r'a=k/2,\quad c=|r_1-r_2|/2,\quad b=\tfrac12\sqrt{k^2-|r_1-r_2|^2}')],'초점r₁,r₂인 타원. 초점이 같으면 반지름k/2인 원이다.','An ellipse with foci r₁,r₂; coincident foci give a radius-k/2 circle.',ck='k가 초점거리보다 커서 단반경이 양수이다.',ce='k exceeds focal separation, so the semiminor axis is positive.')
assert len(b.E)==48
b.save()
